function field(label,name,value,type='number',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function settingsView(){const s=state.settings,c=s.capacity;return `<form id="settings-form"><fieldset><legend>Campaign · fixed delivery commitment</legend><div class="form-grid">${field('Campaign name','name',s.name,'text')}${field('Setup date','start',s.start,'date')}${field('Publishing start','launch',s.launch,'date')}${field('Campaign end','end',s.end,'date')}${field('Approved launch inventory','launchInventory',s.launchInventory,'number','min="0" max="100"')}<label>Total deliverables<input disabled value="100 · 50 per page"></label><label class="wide"><span><input type="checkbox" name="launchWeekendConfirmed" ${s.launchWeekendConfirmed?'checked':''}> Launch weekend work and editor capacity confirmed</span></label></div><p class="hint gap">Date changes do not silently move publication slots or overwrite the original plan. If a new date excludes a slot, move that slot first. Dates use Asia/Kolkata; turnaround is measured in whole days.</p></fieldset><fieldset><legend>Daily capacity · planning estimates</legend><div class="form-grid">${Object.entries({draftPre:'Pre-launch scripts / day',draftNormal:'Normal scripts / weekday',creatorPre:'Pre-launch raw / creator / day',creatorNormal:'Normal raw / creator / weekday',editorPre:'Pre-launch cuts / day',editorNormal:'Normal cuts / weekday',qa:'Reviews / stage / day',batch:'Maximum script assignments / day',weekendDraft:'Weekend scripts after launch',weekendCreator:'Weekend raw / creator after launch',weekendEditor:'Weekend cuts after launch'}).map(([k,l])=>field(l,'cap-'+k,c[k],'number','min="0" max="100"')).join('')}</div><p class="hint gap">The original 6-script batches use up to two creator days. All 100 video slots stay fixed. Capacity changes allocate future work only and can reveal publishing conflicts.</p><div class="form-grid">${field(fmt(add(s.start,35))+' script capacity (accelerated week)','exception-'+add(s.start,35),s.capacityExceptions[add(s.start,35)]?.draft??c.draftNormal)}${field(fmt(add(s.start,36))+' script capacity (accelerated week)','exception-'+add(s.start,36),s.capacityExceptions[add(s.start,36)]?.draft??c.draftNormal)}</div></fieldset>${['pre','normal','urgent'].map(k=>`<fieldset><legend>${{pre:'Pre-launch',normal:'Normal production',urgent:'Urgent video'}[k]} turnaround</legend><div class="form-grid">${['raw','edit','revision','qa'].map(n=>field({raw:'Creator days (calendar)',edit:'Editor days',revision:'Revision days',qa:'QA days'}[n],'rule-'+k+'-'+n,s.rules[k][n],'number','min="0" max="30"')).join('')}<label>Editor / QA / revision day basis<select name="rule-${k}-business"><option value="false" ${!s.rules[k].business?'selected':''}>Calendar days</option><option value="true" ${s.rules[k].business?'selected':''}>Business days (Mon–Fri)</option></select></label></div></fieldset>`).join('')}<div class="toolbar"><button class="primary" type="submit">Save operating rules</button><small>All dependent forecasts recalculate on save.</small></div></form><details class="card gap"><summary>Source plan assumptions</summary><p class="hint">The source totals reconcile: 104 scripts, 100 assignments, 50 raw videos per creator, 100 first cuts and 50 posts per page. Publishing runs for 45 days, with five extra slots per page. Four scripts remain alternatives.</p><p class="hint">The launch needs 18 approvals by 21 October, including six cuts due that day. Weekend turnaround and zero-day QA are assumptions to confirm. The stock forecast in the workbook assumes every cut passes QA. The app counts only actual final approvals. Generic Friday/Saturday follow-up text also appears on 4 December despite no raw work being planned; it is not imported as an actual task.</p><p class="hint">Default source of truth: your campaign constraints. Each video is initially an unstarted delivery slot. Aggregate workbook batches are mapped in order to stable A/B video IDs; titles and actuals were not present.</p></details><div class="card gap"><h2>Occasional tools</h2><div class="toolbar">${btn('Weekly report','view','data-view="Weekly operations"')}${btn('Performance report','view','data-view="Performance"')}${btn('Alternative scripts','reserves')}</div></div><div class="card gap"><h2>Backups and campaign controls</h2><p class="hint">Changes are saved online. Export JSON for a backup. Duplicate starts a new campaign; the previous one remains available through Undo.</p><div class="toolbar">${btn('Download JSON backup','backup')}${btn('Import backup','import')}${btn('Duplicate as fresh campaign','duplicate')}${btn('Reset to source plan','reset','','danger')}</div><input id="import-file" type="file" accept="application/json" hidden></div><div class="card gap"><h2>Change log</h2><div class="audit">${state.audit.slice().reverse().slice(0,50).map(a=>`<p><b>v${a.version}</b> · ${esc(a.description)}<br><small>${esc(a.at)}</small></p>`).join('')||'<p class="hint">No updates recorded yet.</p>'}</div></div>`}
function openDialog(html){dialog.innerHTML=html;dialog.showModal()}
function modal(title,body){return `<div class="dialog-head"><h2>${title}</h2>${btn('✕','close','aria-label="Close dialog"')}</div><div class="dialog-body"><div class="modal-error"></div>${body}</div>`}
function detail(id){const v=state.videos.find(v=>v.id===id),f=forecast(state)[id],k=current(v),r=v.revisions.at(-1);openDialog(modal(`${id} · ${esc(v.page)}`,`<p class="hint">${esc(v.format)} · Version ${v.generation} · ${badge(v.blocker?'blocked':k==='complete'?'complete':'Next: '+LABELS[k],v.blocker?'blocked':GROUP[k]||'complete')}</p><div class="timeline">${STAGES.map(s=>`<span class="${v.actual[s]?'done':''}">${LABELS[s]}</span>`).join('')}</div><div class="toolbar">${k!=='complete'&&ready(v,k)?btn(completionLabel(k),'quick',`data-id="${id}" data-key="${k}"`,'primary'):''}${v.actual.cut&&!v.actual.published&&(!r||r.returned)?btn('Request revision','revision',`data-id="${id}"`):''}${btn('Replace this video','replace',`data-id="${id}"`,'danger')}</div><p class="hint gap">Use the next action above to record progress. Edit an actual date below to correct it.</p><form id="video-form" data-id="${id}"><div class="form-grid">${field('Content title','title',v.title,'text')}${field('Content IP / format','format',v.format,'text')}${field('Scheduled publishing slot','slot',v.slot,'date',`min="${state.settings.launch}" max="${state.settings.end}"`)}<label>Footage quality<select name="quality">${['pending','rejected','usable'].map(x=>`<option ${v.quality===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Priority<select name="urgent"><option value="false" ${!v.urgent?'selected':''}>Normal</option><option value="true" ${v.urgent?'selected':''}>Urgent turnaround</option></select></label>${field('Blocker (blank = unblocked)','blocker',v.blocker,'text')}${field('Script link','scriptUrl',v.scriptUrl||'','url')}${field('Raw footage link','rawUrl',v.rawUrl||'','url')}${field('Cut / final file link','cutUrl',v.cutUrl||'','url')}${field('Published URL','url',v.url,'url')}${field('Missing URL explanation','urlMissingReason',v.urlMissingReason,'text')}<label class="wide">Notes<textarea name="notes" rows="2">${esc(v.notes)}</textarea></label></div><h3 class="gap">Production dates</h3><p class="hint">Original plan is kept for comparison. Current due dates follow actual handoffs. Forecast dates also include available capacity.</p>${STAGES.map(s=>`<div class="stage-row"><div><span class="stage-number">${STAGES.indexOf(s)+1}</span><b>${LABELS[s]}</b><br><small>Original: ${fmt(v.baseline[s])}<br>Due: <b>${fmt(deadline(state,v,s))}</b><br>Forecast: ${fmt(f[s])}</small>${(()=>{const change=scheduleChange(state,{video:v,key:s,original:v.baseline[s],done:v.actual[s],forecast:f[s]},f,today());return change?`<small class="change-reason">${esc(change.reason)}</small>`:''})()}</div><label>Actual date<input name="actual-${s}" type="date" value="${v.actual[s]||''}" max="${today()}"></label><div>${btn('Clear from here','clear-stage',`data-id="${id}" data-key="${s}"`,'link')}</div></div>`).join('')}<details class="gap"><summary>Edit owners and deadline overrides</summary><p class="hint">Blank deadline uses the dependency rule. All overrides are saved in the change log. Publishing uses the slot field above.</p><div class="form-grid">${STAGES.filter(s=>s!=='published').concat(r?['revision']:[]).map(s=>`<label>${LABELS[s]} · due override<input name="due-${s}" type="date" value="${v.overrides[s]||''}"></label><label>${LABELS[s]} · owner<input name="owner-${s}" value="${esc(owner(v,s))}"></label>`).join('')}</div></details>${v.revisions.length?`<h3 class="gap">Revision rounds</h3>${v.revisions.map((r,i)=>`<div class="form-grid">${field('Round '+(i+1)+' requested','rev-request-'+i,r.requested,'date',`max="${today()}"`)}${field('Returned','rev-return-'+i,r.returned,'date',`max="${today()}"`)}${field('Feedback','rev-note-'+i,r.note,'text')}</div>`).join('')}`:''}<details class="gap"><summary>Performance metrics</summary><div class="form-grid">${['views','likes','shares','saves','comments','clicks','signups'].map(m=>field(m,'metric-'+m,v.metrics[m]??'','number','min="0"')).join('')}</div><p class="hint">Blank means not recorded. No sample metrics are supplied.</p></details><div class="toolbar gap"><button class="primary" type="submit">Save changes</button>${btn('Close','close')}</div></form>${v.history.length?`<h3 class="gap">Replacement history · excluded from totals</h3>${v.history.map(h=>`<p class="hint">Generation ${h.generation} · replaced ${fmt(h.date)} · ${esc(h.reason)}<br>Previous live date ${fmt(h.actual.published)} · ${esc(h.url)}</p>`).join('')}`:''}`))}
function quick(id,k){const v=state.videos.find(v=>v.id===id);if(dialog.open)dialog.close();openDialog(modal(`${LABELS[k]} · ${id}`,`<form id="action-form" data-id="${id}" data-key="${k}"><p>${k==='usable'?'Confirm audio, framing, format, hook and product claims. Only accept footage that is usable.':k==='approved'?'Approve the actual final cut after checking hook, captions, claims, CTA and audio.':'Record this stage only when the work has actually happened.'}</p><div class="form-grid">${field('Actual completion / receipt date','date',date>today()?today():date,'date',`max="${today()}" required`)}${k==='published'?field('Published URL','url',v.url,'url')+field('Or missing URL explanation','urlMissingReason',v.urlMissingReason,'text'):''}</div><div class="toolbar gap"><button type="submit" class="primary">${k==='approved'?'Approve final video':k==='usable'?'Accept usable footage':'Record actual'}</button>${k==='approved'?btn('Request revision','revision',`data-id="${id}"`):''}${btn('Cancel','close')}</div></form>`))}
function bulk(key,ids,quantity){const chosen=ids.slice(0,quantity);openDialog(modal(`Record ${LABELS[key].toLowerCase()}`,`<form id="bulk-form" data-key="${key}"><p>Select exactly which videos were completed. Unselected videos remain pending.</p>${field('Actual date','date',date>today()?today():date,'date',`max="${today()}" required`)}${ids.map(id=>`<label class="checklist"><input name="ids" value="${id}" type="checkbox" ${chosen.includes(id)?'checked':''}>${id} · ${esc(state.videos.find(v=>v.id===id).page)}</label>`).join('')}<div class="toolbar gap"><button class="primary" type="submit">Save selected actuals</button>${btn('Cancel','close')}</div></form>`))}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function exportCSV(){const headers=['ID','Creator','Page','Format','Title','Next action','Quality',...STAGES.map(k=>'Actual '+k),...STAGES.map(k=>'Original '+k),...STAGES.map(k=>'Due '+k),'Revision count','Revision due','Publish slot','Script link','Raw link','Cut link','URL','Missing URL reason','Blocker','Notes','Metrics'];const rows=state.videos.map(v=>[v.id,v.creator,v.page,v.format,v.title,current(v),v.quality,...STAGES.map(k=>v.actual[k]||''),...STAGES.map(k=>v.baseline[k]),...STAGES.map(k=>deadline(state,v,k)),v.revisions.length,deadline(state,v,'revision'),v.slot,v.scriptUrl,v.rawUrl,v.cutUrl,v.url,v.urlMissingReason,v.blocker,v.notes,JSON.stringify(v.metrics)]);const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download('wave-production.csv','\uFEFF'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,k=b.dataset.key;
 try{
 if(a==='view'){view=b.dataset.view;render()}
 else if(a==='late-board'){view='Production board';filter.status='overdue';render()}
 else if(a==='capacity'){openDialog(modal('Writing capacity for a day',`<form id="capacity-form"><p>Enter how many scripts can be written on this date. Use 0 for a missed day. This moves unfinished work, never records it as completed.</p>${field('Date','day',date,'date','required')}${field('Scripts available to write','capacity',state.settings.capacityExceptions?.[date]?.draft??(date<state.settings.launch?state.settings.capacity.draftPre:[0,6].includes(new Date(date+'T12:00Z').getUTCDay())?state.settings.capacity.weekendDraft:state.settings.capacity.draftNormal),'number','min="0" max="100" required')}<button class="primary gap">Update remaining plan</button></form>`))}
 else if(a==='today'){date=today();render()}
 else if(a==='close')dialog.close();
 else if(a==='detail'){if(dialog.open)dialog.close();detail(id)}
 else if(a==='quick')quick(id,k);
 else if(a==='progress'){const next=structuredClone(state),v=next.videos.find(v=>v.id===id);v.inProgress=v.inProgress===k?'':k;if(await save(next,`${id}: ${v.inProgress?'started':'paused'} ${LABELS[k]}`)){dialog.close();detail(id)}}
 else if(a==='bulk'){const q=Number(b.closest('.task-group').querySelector('.actual-count').value),ids=b.dataset.ids.split(',');if(!Number.isInteger(q)||q<1||q>ids.length)throw Error('Enter a quantity between 1 and '+ids.length);bulk(k,ids,q)}
 else if(a==='day'){date=b.dataset.date;render()}
 else if(a==='calendar-day'){view='Calendar';date=b.dataset.date;render()}
 else if(a==='mode'){calendarMode=b.dataset.mode;render()}
 else if(a==='period'){if(calendarMode==='Week')date=add(date,7*Number(b.dataset.dir));else{const d=new Date(date+'T12:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.dir));date=d.toISOString().slice(0,10)}render()}
 else if(a==='week'){date=add(date,7*Number(b.dataset.dir));render()}
 else if(a==='undo'){if(await save(null,'Undo last update','/api/undo')){if(dialog.open)dialog.close()}}
 else if(a==='export')exportCSV();
 else if(a==='backup')download('wave-backup.json',JSON.stringify(state,null,2),'application/json');
 else if(a==='import')document.querySelector('#import-file').click();
 else if(a==='clear-filters'){filter={creator:'',status:'',format:'',search:'',from:'',to:''};render()}
 else if(a==='clear-stage'){if(!confirm('Clear '+LABELS[k]+' and all later actuals for '+id+'? Undo is available.'))return;const next=structuredClone(state),v=next.videos.find(v=>v.id===id);STAGES.slice(STAGES.indexOf(k)).forEach(s=>delete v.actual[s]);if(STAGES.indexOf(k)<=6)v.revisions=[];if(STAGES.indexOf(k)<=4)v.quality='pending';v.url='';v.urlMissingReason='';if(await save(next,`${id}: corrected by clearing ${k} and downstream actuals`)){dialog.close();detail(id)}}
 else if(a==='revision'){if(dialog.open)dialog.close();openDialog(modal(`Request revision · ${id}`,`<form id="revision-form" data-id="${id}"><div class="form-grid">${field('Request date','date',today(),'date',`max="${today()}" required`)}<label class="wide">Consolidated feedback<textarea name="note" required rows="3"></textarea></label></div><p class="hint">This removes final approval and scheduling until a revised cut is received and approved.</p><button class="primary" type="submit">Request changes</button></form>`))}
 else if(a==='replace'){const note=prompt('Why is this video being replaced? Its previous history will remain, but it will no longer count as published.');if(!note)return;const next=structuredClone(state);applyAction(next,id,'replace',today(),{note});if(await save(next,`${id}: replacement — ${note}`)){dialog.close();detail(id)}}
 else if(a==='reset'){if(!confirm('Reset to the source plan? Export JSON first for an independent backup. Undo retains the previous state.'))return;await save(null,'Reset to original plan','/api/reset')}
 else if(a==='duplicate'){openDialog(modal('Start a new campaign',`<form id="duplicate-form"><p>Creates a fresh 100-video plan in this workspace. All dates shift by the setup-date difference. Existing work stays in undo history; export JSON first for a separate permanent backup.</p><div class="form-grid">${field('Campaign name','name','New campaign','text','required')}${field('New setup date','start',state.settings.start,'date','required')}</div><div class="toolbar gap"><button type="submit" class="primary">Create fresh campaign</button>${btn('Cancel','close')}</div></form>`))}
 else if(a==='reserves'){openDialog(modal('Alternative scripts',`<form id="reserve-form"><p class="hint">Four alternatives are scripted options, not extra video assets. Replacing an undrafted script uses the same video slot.</p>${state.reserves.map(r=>`<fieldset><legend>${r.id}</legend><div class="form-grid">${field('Title',r.id+'-title',r.title,'text')}${field('Actual drafted',r.id+'-drafted',r.drafted,'date',`max="${today()}"`)}${field('Actual approved',r.id+'-approved',r.approved,'date',`max="${today()}"`)}</div>${r.usedBy?`<p class="hint">Used by ${r.usedBy}</p>`:r.approved?`<div class="toolbar gap"><select id="use-${r.id}" aria-label="Delivery slot for ${r.id}">${state.videos.filter(v=>!v.actual.drafted).map(v=>`<option>${v.id}</option>`).join('')}</select>${btn('Use on this video','use-reserve',`data-id="${r.id}"`)}</div>`:''}</fieldset>`).join('')}<button class="primary" type="submit">Save alternatives</button></form>`))}
 else if(a==='use-reserve'){const vid=document.querySelector('#use-'+id).value;if(!vid)throw Error('No undrafted video slots remain');const next=structuredClone(state),r=next.reserves.find(r=>r.id===id),v=next.videos.find(v=>v.id===vid);v.actual.drafted=r.drafted;v.actual.scriptApproved=r.approved;v.title=r.title;v.notes+='\nAlternative '+id+' used.';r.usedBy=vid;if(await save(next,`${id}: used for ${vid}`))dialog.close()}
 }catch(err){notify(err.message)}
});
document.addEventListener('change',async e=>{const el=e.target;
 if(el.id==='view-date'&&el.value){date=el.value;render()}
 else if(el.id==='calendar-basis'){calendarBasis=el.value;render()}
 else if(el.id.startsWith('filter-')){filter[el.id.slice(7)]=el.value;render()}
 else if(el.id==='search'){filter.search=el.value;render()}
 else if(el.dataset.setup){const next=structuredClone(state);next.setup.find(x=>x.id===el.dataset.setup).done=el.checked;await save(next,'Updated setup checklist')}
 else if(el.id==='import-file'&&el.files[0]){try{const next=JSON.parse(await el.files[0].text());if(!confirm('Restore this backup? Current data remains in undo history.'))return;await save(next,'Imported JSON backup','/api/import')}catch(err){notify('Invalid backup: '+err.message)}}
});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=new FormData(form),next=structuredClone(state);let description='';
 try{
 if(form.id==='duplicate-form'){if(await save(null,'Created new campaign','/api/duplicate',{name:data.get('name'),start:data.get('start')}))dialog.close();return}
 if(form.id==='action-form'){applyAction(next,form.dataset.id,form.dataset.key,data.get('date'),{url:data.get('url'),urlMissingReason:data.get('urlMissingReason')});description=`${form.dataset.id}: ${LABELS[form.dataset.key]} on ${data.get('date')}`}
 else if(form.id==='bulk-form'){const ids=data.getAll('ids');if(!ids.length)throw Error('Select at least one video');for(const id of ids)applyAction(next,id,form.dataset.key,data.get('date'));description=`${LABELS[form.dataset.key]}: ${ids.join(', ')} on ${data.get('date')}`}
 else if(form.id==='revision-form'){applyAction(next,form.dataset.id,'requestRevision',data.get('date'),{note:data.get('note')});description=`${form.dataset.id}: revision requested — ${data.get('note')}`}
 else if(form.id==='capacity-form'){const day=data.get('day'),capacity=Number(data.get('capacity'));next.settings.capacityExceptions[day]={draft:capacity};description=`Writing capacity ${day}: ${capacity} scripts; unfinished work carried forward`}
 else if(form.id==='settings-form'){const s=next.settings;for(const k of ['name','start','launch','end'])s[k]=data.get(k);s.launchInventory=Number(data.get('launchInventory'));s.launchWeekendConfirmed=data.has('launchWeekendConfirmed');for(const k of Object.keys(s.capacity))s.capacity[k]=Number(data.get('cap-'+k));for(const k of ['pre','normal','urgent']){for(const n of ['raw','edit','revision','qa'])s.rules[k][n]=Number(data.get('rule-'+k+'-'+n));s.rules[k].business=data.get('rule-'+k+'-business')==='true'}for(const d of [add(state.settings.start,35),add(state.settings.start,36)])s.capacityExceptions[d]={draft:Number(data.get('exception-'+d))};description='Changed campaign operating rules: '+JSON.stringify(s)}
 else if(form.id==='video-form'){const v=next.videos.find(v=>v.id===form.dataset.id),before=JSON.stringify(v);for(const k of ['title','format','slot','quality','blocker','url','urlMissingReason','notes','scriptUrl','rawUrl','cutUrl'])v[k]=data.get(k);v.urgent=data.get('urgent')==='true';for(const s of STAGES){const val=data.get('actual-'+s);if(val)v.actual[s]=val;else delete v.actual[s];if(data.has('due-'+s)){if(data.get('due-'+s))v.overrides[s]=data.get('due-'+s);else delete v.overrides[s]}if(data.has('owner-'+s))v.owners[s]=data.get('owner-'+s)}if(data.has('due-revision')){if(data.get('due-revision'))v.overrides.revision=data.get('due-revision');else delete v.overrides.revision;v.owners.revision=data.get('owner-revision')}for(const m of ['views','likes','shares','saves','comments','clicks','signups'])v.metrics[m]=data.get('metric-'+m)===''?'':Number(data.get('metric-'+m));v.revisions.forEach((r,i)=>{r.requested=data.get('rev-request-'+i);r.returned=data.get('rev-return-'+i);r.note=data.get('rev-note-'+i)});const old=JSON.parse(before);description=`${v.id}: `+Object.keys(v).filter(k=>JSON.stringify(v[k])!==JSON.stringify(old[k])).map(k=>`${k}: ${JSON.stringify(old[k])} → ${JSON.stringify(v[k])}`).join('; ')}
 else if(form.id==='reserve-form'){for(const r of next.reserves){for(const k of ['title','drafted','approved'])r[k]=data.get(r.id+'-'+k)}description='Updated alternative scripts'}
 else return;
 if(await save(next,description)){if(dialog.open)dialog.close()}
 }catch(err){const box=dialog.open?dialog.querySelector('.modal-error'):null;if(box)box.innerHTML=`<div class="error">${esc(err.message)}</div>`;else notify(err.message)}
});
load();

